# Define a function that finds the sum of digits
def sum_of_digits(n):
    # Check if n is equal to 0
    if n == 0:
        return 0
    else:
        # Recursively call the function with n mod 10 (to get the last digit) and n//10 (to remove the last digit)
        return n % 10 + sum_of_digits(n // 10)

