class HashMap:
    def __init__(self):
        self.array_size = 10
        self.array = [None] * self.array_size

    def hash(self, key):
        hash_value = ord(key[0])
        return hash_value % self.array_size

    def insert(self, key, value):
        key_hash = self.hash(key)
        key_value = [key, value]

        if self.array[key_hash] is None:
            self.array[key_hash] = list([key_value])
            return True
        else:
            for pair in self.array[key_hash]:
                if pair[0] == key:
                    pair[1] = value
                    return True
            self.array[key_hash].append(key_value)
            return True

    def get(self, key):
        key_hash = self.hash(key)
        if self.array[key_hash] is not None:
            for pair in self.array[key_hash]:
                if pair[0] == key:
                    return pair[1]
        return None

    def delete(self, key):
        key_hash = self.hash(key)

        if self.array[key_hash] is None:
            return False

        for i in range (0, len(self.array[key_hash])):
            if self.array[key_hash][i][0] == key:
                self.array[key_hash].pop(i)
                return True

